'use strict';
// Experimental route seam. Loaded only by the isolated React preview, never index.html/SW.
(()=>{let identity=null,sessionVersion=0;window.ATRY_SERVICES_PORT={
 scope(){if(identity!==state.me){identity=state.me;sessionVersion++;}return state.me?.user&&state.business?{sessionVersion,userId:state.me.user.id,businessId:state.business.id,role:state.business.role,sector:state.business.sector||'',accessEnabled:state.entitlements?.access_enabled===true}:null;},
 request:(route,options)=>api(route,options),
 publish(scope,catalog){const now=this.scope();if(!now||now.sessionVersion!==scope.sessionVersion||now.userId!==scope.userId||now.businessId!==scope.businessId||now.role!==scope.role||now.accessEnabled!==scope.accessEnabled)return;state.services=structuredClone(catalog.services);state.staffList=structuredClone(catalog.staff);},
 createHost(view='servicios',title='Servicios'){state.dialog=null;const marker=view==='servicios'?'data-react-services-root':view==='clientes'?'data-react-customers-root':'data-react-native-root';setScreen('<div data-react-view="'+esc(view)+'" '+marker+'></div>',title);return document.querySelector('[data-react-view]');},
 user:()=>structuredClone(state.me.user),
 weeklyModel:(rows,end)=>agendaWeeklyModel(rows,end),
 dayTitle:day=>agendaDayTitle(day),
 openActivity(day){state.dateAgenda=day;state.agendaMobileDate=day;state.agendaMode='dia';state.agendaAttention=false;state.agendaSearch='';state.agendaStaff='';state.agendaResource='';state.agendaStatusFilter='';nav('/app/agenda');},
 resetAgendaToday(){state.dateAgenda=today();state.agendaMode='dia';state.agendaStaff='';state.agendaStatusFilter='';state.agendaSearch='';},
 notificationContext:()=>({planLabel:subscriptionPlan(state.business),mailProvider:state.config?.mail_provider||'',usage:structuredClone(state.entitlements.mail_usage||null)}),
 photoRequest:(route,body)=>photoRequest(route,body),
 photoBytes:image=>photoCore.bytes(image),
 async refreshPermissions(){await refreshIdentity();state.business=null;await renderApp();},
 completedOnboarding(){state.business=null;nav('/app/inicio');},
 demo:()=>Boolean(window.ATRY_DEMO?.enabled),
 business:()=>structuredClone(state.business),
 capability:name=>hasCapability(name),
 dateAgenda:()=>state.dateAgenda,
 goAgenda(date){state.dateAgenda=date;nav('/app/agenda');},
 navigate:route=>nav(route),
 publishCustomers(rows){state.customers=structuredClone(rows);},
 whatsapp:()=>waCore,
 bookingIssues:(...args)=>agendaBookingIssues(...args),
 exactContacts:(...args)=>agendaExactContacts(...args),
 contactKey:(...args)=>agendaContactKey(...args),
 icon:name=>iconPaths[name]||iconPaths.info,
 serviceIcon:(sector,name)=>sectorIcon(sector,name),
 notify:(message,error)=>toast(message,error)
};})();
